import React from "react";
import { PieChart, Pie, Cell } from "recharts";
import { PencilSquareIcon } from "@heroicons/react/24/solid";

const COLORS = ["#3b82f6", "#e5e7eb"];

function getMonthsRemaining(deadline) {
  const now = new Date();
  const end = new Date(deadline);
  return Math.max(
    1,
    (end.getFullYear() - now.getFullYear()) * 12 + (end.getMonth() - now.getMonth())
  );
}

const GoalCard = ({ goal, onRemove, onEdit, priorityRank }) => {
  const percent = Math.min((goal.saved / goal.amount) * 100, 100);
  const data = [
    { name: "Saved", value: percent },
    { name: "Remaining", value: 100 - percent },
  ];

  // Fallback calculation for monthly savings
  let monthlySavings = goal.monthlySavings;
  if (!monthlySavings || monthlySavings === 0) {
    const months = getMonthsRemaining(goal.deadline);
    const amountLeft = Math.max(goal.amount - (goal.saved || 0), 0);
    monthlySavings = +(amountLeft / months).toFixed(2);
  }

  return (
    <div className="bg-gradient-to-br from-blue-100 via-white to-emerald-100 rounded-2xl shadow-md p-4 flex flex-col items-center relative border border-blue-50 w-full max-w-lg transition-all hover:shadow-xl hover:-translate-y-1 active:scale-[0.98]">
      {priorityRank && (
        <div className="absolute -top-3 left-1/2 -translate-x-1/2 bg-primary text-white text-xs font-bold px-3 py-1 rounded-full shadow z-10">
          Priority #{priorityRank}
        </div>
      )}
      <button
        className="absolute top-2 right-2 text-xs text-gray-400 hover:text-red-500"
        onClick={() => onRemove(goal.id)}
        title="Remove Goal"
      >
        ×
      </button>
      <button
        className="absolute top-2 left-2 text-xs text-primary hover:bg-blue-200 rounded-full p-1"
        onClick={() => onEdit(goal)}
        title="Edit Goal"
      >
        <PencilSquareIcon className="h-5 w-5" />
      </button>
      <PieChart width={64} height={64} className="mb-2">
        <Pie
          data={data}
          cx={32}
          cy={32}
          innerRadius={20}
          outerRadius={28}
          startAngle={90}
          endAngle={-270}
          dataKey="value"
        >
          {data.map((entry, idx) => (
            <Cell key={`cell-${idx}`} fill={COLORS[idx]} />
          ))}
        </Pie>
      </PieChart>
      <div className="text-base font-semibold mb-0.5 text-primary drop-shadow text-center truncate w-full">{goal.name}</div>
      <div className="text-xs text-emerald-700 mb-1">By {goal.deadline}</div>
      <div className="w-full mb-1">
        <div className="flex justify-between text-xs mb-0.5">
          <span className="text-blue-700">${goal.saved.toLocaleString()} saved</span>
          <span className="text-emerald-700">${goal.amount.toLocaleString()} target</span>
        </div>
        <div className="w-full h-1.5 bg-blue-100 rounded">
          <div
            className="h-1.5 bg-primary rounded"
            style={{ width: `${percent}%` }}
          ></div>
        </div>
      </div>
      <div className="mt-1 text-xs bg-blue-200 text-primary px-2 py-0.5 rounded-full font-medium shadow">
        Save ${monthlySavings.toLocaleString()} / month
      </div>
    </div>
  );
};

export default GoalCard;
